def shoot_segments(grid, bg=None):
    """Each same-color segment (>=2 cells) along a row, column, or diagonal extends both ways to the edge, stopped by other colors."""
    if bg is None:
        from collections import Counter
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    cells={}
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg: cells.setdefault(grid[i][j],[]).append((i,j))
    dirs=[(0,1),(1,0),(1,1),(1,-1)]
    for color,pts in cells.items():
        ps=set(pts)
        for dr,dc in dirs:
            # starts of segments: cell whose predecessor in dir not same color
            for (i,j) in pts:
                if (i-dr,j-dc) not in ps:
                    seg=[]; a,b=i,j
                    while (a,b) in ps: seg.append((a,b)); a,b=a+dr,b+dc
                    if len(seg)<2: continue
                    for sign in (1,-1):
                        a,b=seg[0][0]-dr*0,seg[0][1]  # start
                        a,b=(i,j) if sign==-1 else seg[-1]
                        a,b=a+sign*dr,b+sign*dc
                        while 0<=a<h and 0<=b<w and out[a][b]==bg:
                            out[a][b]=color; a,b=a+sign*dr,b+sign*dc
    return out

